mapper.select:
SELECT count(*)
  FROM resource_node
 WHERE tenant_id = #{param1}
   AND id = #{param2}
   AND kind = 'island'
   AND deleted_at IS NULL

SELECT island_id
  FROM workflow
 WHERE tenant_id = #{param1}
   AND id = #{param2}

SELECT count(*)
  FROM workflow
 WHERE tenant_id = #{param1}
   AND code = #{param2}

SELECT w.id, w.code, w.name, w.category,
       (SELECT count(*) FROM workflow_node n
         WHERE n.workflow_id = w.id AND n.node_type = 'task') AS task_count
  FROM workflow w
 WHERE w.tenant_id = #{tenantId}

   AND w.category = #{category}

 ORDER BY w.updated_at DESC NULLS LAST, w.id DESC LIMIT #{limit}
